def q(key, mirror, section, tasks, title, sub, deps, what, how, tip=None, xp=40, extra=""):
    lines = [f'"&eWhat:&r {what}"', f'"&eHow:&r {how}"'] + ([f'"&eTip:&r {tip}"'] if tip else [])
    return (f'    Q("{key}", 0, 0, {tasks}, "{title}", subtitle="{sub}", deps={deps!r}, xp={xp}, mirror="{mirror}", section={section}{extra}, desc=[\n        '
            + ",\n        ".join(lines) + "]),\n")


